"use client";
import React, { useEffect, useState } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import Menu from "./menu";
import { getCookie } from "cookies-next";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChevronDown, faCheck } from "@fortawesome/free-solid-svg-icons";
import { apiClient } from "@/lib/apiClient";

type PrefKey = "activities" | "preffered_travel_styles" | "categories" | "preffer_lodgings";
type FilterItem = { name: string; slug: string };

const byName = (a: FilterItem, b: FilterItem) => {
  if (a.name < b.name) return -1;
  if (a.name > b.name) return 1;
  return 0;
};

export default function TravelPreferences() {
  const [userTravelPreferencesLoading, setUserTravelPreferencesLoading] = useState(true);
  const [filterListLoading, setFilterListLoading] = useState(true);
  const [submitLoading, setSubmitLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [submitStatus, setSubmitStatus] = useState("");
  const [openKey, setOpenKey] = useState<PrefKey | null>(null);
  const [filterList, setFilterList] = useState({
    activities: [{ id: "", name: "", slug: "" }],
    categories: [{ id: "", name: "", slug: "" }],
    prefferedTravelStyles: [{ name: "", slug: "" }],
    prefferLodgingLevels: [{ name: "", slug: "" }],
  });

  const [userTravelPreferences, setUserTravelPreferences] = useState<any>({
    activities: [],
    categories: [],
    preffered_travel_styles: [],
    preffer_lodgings: [],
  });

  const fetchFilterList = async () => {
    // apiv3 B2C (login gerekmez): GET /profile/filter-list
    return apiClient<any>("/profile/filter-list");
  };

  const fetchTravelPreferences = async () => {
    // apiv3 Account (Sanctum): GET /b2c/profile/travel-preferences
    return apiClient<any>("/b2c/profile/travel-preferences", {
      auth: "sanctum",
      token: getCookie("auth-token-v3") as string,
    });
  };

  useEffect(() => {
    fetchFilterList().then((res: any) => {
      setFilterList({
        activities: res.activities,
        categories: res.categories,
        prefferedTravelStyles: res.prefferedTravelStyles,
        prefferLodgingLevels: res.prefferLodgingLevels,
      });
      setFilterListLoading(false);
    });

    fetchTravelPreferences().then((res: any) => {
      setUserTravelPreferences({
        activities: res.activities,
        categories: res.categories,
        preffered_travel_styles: res.preffered_travel_styles,
        preffer_lodgings: res.preffer_lodgings,
      });
      setUserTravelPreferencesLoading(false);
    });
  }, []);

  const updateSubmit = async () => {
    setSubmitStatus("");
    setErrorMessage("");

    try {
      setSubmitLoading(true);

      // apiv3 Account (Sanctum): POST /b2c/profile/travel-preferences
      await apiClient("/b2c/profile/travel-preferences", {
        method: "POST",
        body: userTravelPreferences,
        auth: "sanctum",
        token: getCookie("auth-token-v3") as string,
      });

      setErrorMessage("");
      setSubmitStatus("success");

      setTimeout(() => {
        window.location.reload();
      }, 500);
    } catch (error: any) {
      setSubmitStatus("error");
      setErrorMessage("Something went wrong. Please try again later or contact support.");
    }
    setSubmitLoading(false);
  };

  const toggleItem = (key: PrefKey, slug: string) => {
    setUserTravelPreferences((prev: any) => {
      const current: string[] = Array.isArray(prev[key]) ? prev[key] : [];
      return {
        ...prev,
        [key]: current.includes(slug)
          ? current.filter((s) => s !== slug)
          : [...current, slug],
      };
    });
  };

  const sections: { key: PrefKey; title: string; options: FilterItem[] }[] = [
    { key: "activities", title: "Preferred Activities", options: [...filterList.activities].sort(byName) },
    { key: "preffered_travel_styles", title: "Preferred Travel Style", options: [...filterList.prefferedTravelStyles].sort(byName) },
    { key: "categories", title: "Preferred Categories", options: [...filterList.categories].sort(byName) },
    { key: "preffer_lodgings", title: "Preferred Lodging Level", options: [...filterList.prefferLodgingLevels].sort(byName) },
  ];

  const loading = filterListLoading || userTravelPreferencesLoading;

  return (
    <main className="tw-font-display">
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
        <Breadcrumb items={[{ pageTitle: "Profile", pageUrl: "/profile" }]} />
        <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Travel Preferences
        </h1>

        <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
          <div>
            <Menu />
          </div>
          <div>
            {loading && (
              <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
              </div>
            )}

            {!loading && (
              <div className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
                <h2 className="tw-mb-1 tw-text-lg tw-font-bold tw-text-[#14101c]">Your Travel Preferences</h2>
                <p className="tw-mb-5 tw-mt-0 tw-text-sm tw-text-[#6b6577]">
                  Update your travel preferences below to help us tailor your recommendations and offers.
                </p>

                {submitStatus == "error" && errorMessage && (
                  <div className="tw-mb-4 tw-rounded-xl tw-border tw-border-solid tw-border-[#f3c2c2] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-text-[#b23838]">
                    {errorMessage}
                  </div>
                )}
                {submitStatus == "success" && (
                  <div className="tw-mb-4 tw-rounded-xl tw-border tw-border-solid tw-border-[#bfe6cd] tw-bg-[#eafaf0] tw-px-4 tw-py-3 tw-text-sm tw-text-[#1f8a4c]">
                    Your preferences have been saved successfully.
                  </div>
                )}

                <div className="tw-flex tw-flex-col tw-gap-3">
                  {sections.map((section) => {
                    const isOpen = openKey === section.key;
                    const selected: string[] = Array.isArray(userTravelPreferences[section.key])
                      ? userTravelPreferences[section.key]
                      : [];
                    return (
                      <div
                        key={section.key}
                        className="tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ece9f1]"
                      >
                        <button
                          type="button"
                          onClick={() => setOpenKey(isOpen ? null : section.key)}
                          aria-expanded={isOpen}
                          className="tw-flex tw-w-full tw-items-center tw-justify-between tw-border-0 tw-bg-[#faf9fc] tw-px-4 tw-py-3.5 tw-text-left tw-text-sm tw-font-semibold tw-uppercase tw-tracking-wide tw-text-[#14101c]"
                        >
                          <span className="tw-flex tw-items-center tw-gap-2">
                            {section.title}
                            {selected.length > 0 && (
                              <span className="tw-rounded-full tw-bg-[#854ec9] tw-px-2 tw-py-0.5 tw-text-[11px] tw-font-bold tw-text-white tw-normal-case">
                                {selected.length}
                              </span>
                            )}
                          </span>
                          <FontAwesomeIcon
                            icon={faChevronDown}
                            className={`tw-text-[#9b95a8] tw-transition-transform tw-duration-200 ${isOpen ? "tw-rotate-180" : ""}`}
                          />
                        </button>

                        {isOpen && (
                          <div className="tw-flex tw-max-h-[320px] tw-flex-wrap tw-gap-2 tw-overflow-y-auto tw-p-4">
                            {section.options.map((item) => {
                              const active = selected.includes(item.slug);
                              return (
                                <button
                                  type="button"
                                  key={item.slug}
                                  onClick={() => toggleItem(section.key, item.slug)}
                                  className={`tw-inline-flex tw-cursor-pointer tw-select-none tw-items-center tw-gap-1.5 tw-rounded-full tw-border tw-border-solid tw-px-3.5 tw-py-1.5 tw-text-sm tw-font-medium tw-transition-all ${
                                    active
                                      ? "tw-border-[#854ec9] tw-bg-[#854ec9] tw-text-white tw-shadow-[0_6px_16px_rgba(133,78,201,0.30)]"
                                      : "tw-border-[#e2dded] tw-bg-white tw-text-[#5d556c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]"
                                  }`}
                                >
                                  {active && <FontAwesomeIcon icon={faCheck} className="tw-text-[10px]" />}
                                  {item.name}
                                </button>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>

                <div className="tw-mt-6">
                  {submitLoading ? (
                    <button
                      type="button"
                      disabled
                      className="tw-inline-flex tw-w-full tw-items-center tw-justify-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-opacity-70"
                    >
                      <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                      Loading...
                    </button>
                  ) : (
                    <button
                      type="button"
                      onClick={updateSubmit}
                      className="tw-w-full tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-transition-colors hover:tw-bg-[#6a3da4]"
                    >
                      Save
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
